INSERT INTO attraction (id, slug, latitude, longitude, google_maps_url, active) VALUES ('5a09d762-ae0a-520e-a0da-b99d9a958a14', 'paring-hegyseg', 45.3935791, 23.4461405, 'https://www.google.com/maps/place/Telescaun+Par%C3%A2ng/@45.6926924,23.0696974,9.96z/data=!4m6!3m5!1s0x474dc72754b8f21f:0xf70e327de2828148!8m2!3d45.3935791!4d23.4461405!16s%2Fg%2F1tgx5cvr?authuser=0&entry=ttu', TRUE);
INSERT INTO attraction_translation (attraction_id, language_code, name, short_description, detailed_description, admission_information, practical_information) VALUES ('5a09d762-ae0a-520e-a0da-b99d9a958a14', 'hu', 'Páring-hegység', 'A Déli-Kárpátok harmadik legnagyobb hegysége, glaciális tavakkal és síközponttal.', '„…Pásztorkunyhóm meredek havasi rét aljára épült. A meredek hegyoldal grandiózus templom tetejére emlékeztetett, mely fölött több száz méteres sziklafal, mint templomtorony emelkedett a csillagos ég felé A kunyhó mellett cirbolyafák álltak őrt, alatta sötét fenyves terült el: érintetlen őserdő…” (Maderspach Viktor, Váradi Péter Pál hivatkozása)
Váradi Péter Pál Erdély, Kárpátok koronája könyvében olvashatjuk Maderspach Viktor sorait melyből kitűnik, hogy a Páring-hegység egy érintetlen vadregényes térség.
A glaciális domborzat alkotta térség, a Déli-Kárpátok harmadik legnagyobb hegysége. Legmagasabb csúcsa a Nagy-Páring 2519 méter. A gerincet egységes magas felszín jellemzi, a könnyű megközelíthetőségével és a viszonylag
A Zsil folyó bal oldalán fekvő hegység könnyen megközelíthető a Petrozsényi-medence felől, mely térség oly híres volt bányászatáról. Északon a Zsil és Lotru mellékvizeinek völgyei szelik át. A keleti főgerinc a Kapacina vonulatához kapcsolódik. A hegységet körülveszik a Vulkán-, Retyezát-hegységek és a Kudzsiri- meg a Szebeni-havasok.
A Páring nyugati lejtőjén síközpont terül el. A hegység turizmusa az 1900-as évek kezdetén kezd kibontakozni. Ekkor építik meg az első menedékházat. Az 1969-1972 között épült felvonó 1073 méterről 1685 méterre szállítja a turistákat. Innen könnyű megközelíteni a 2074 méteren levő Kis-Páringot. Jelenleg körülbelül 6,8 kilométer sípálya és sok vendégfogadóhely várja az érdeklődőket. (Nagy Balázs, 2010:9-23)', 'Libegőzés 1700 méteres magasságig: 42 lej/fő oda-vissza.', NULL);
INSERT INTO attraction_collection (attraction_id, collection_id, display_order) VALUES ('5a09d762-ae0a-520e-a0da-b99d9a958a14', 'e4b76131-d997-51e2-a1d7-c64a2f10c2d2', 10);
INSERT INTO attraction (id, slug, latitude, longitude, google_maps_url, active) VALUES ('05a8713a-edea-5469-a55b-dcda7e94ac5c', 'veka-szurdok', 45.5333, 23.0833, 'https://maps.app.goo.gl/QLx9tLovDLkFTfHr5', TRUE);
INSERT INTO attraction_translation (attraction_id, language_code, name, short_description, detailed_description, admission_information, practical_information) VALUES ('05a8713a-edea-5469-a55b-dcda7e94ac5c', 'hu', 'Véka-szurdok', 'A Buta-patak vájta keskeny, 100 méteres szurdok a Gredistye-Muncsel Csoklovina Nemzeti Parkban.', 'A Véka-szurdokot a Buta-patak képezte mielőtt a Zsilbe ömlik. A Gredistye-Muncsel Csoklovina Nemzeti Parkhoz tartozik. Természeti különlegesség. A 100 méteres szurdok szélessége csupán pár méter. Különlegessége, hogy a szűk szorost magas falak követik, melyet a víz kedvére alakított az idő során. (Dorina Niță, 2015:130)', 'Belépő: 5 lej/fő.', 'Amennyiben az időjárás engedi, a szurdok szandálban vagy mezítláb is bejárható. Papucs használatát nem ajánlom, mivel a pataknak van egy kis sodrása.');
INSERT INTO attraction_collection (attraction_id, collection_id, display_order) VALUES ('05a8713a-edea-5469-a55b-dcda7e94ac5c', 'e4b76131-d997-51e2-a1d7-c64a2f10c2d2', 20);
INSERT INTO attraction (id, slug, latitude, longitude, google_maps_url, active) VALUES ('34fe6663-359b-5f14-a950-a3714a5d352d', 'boli-barlang', 45.5719, 22.98, 'https://maps.app.goo.gl/ZGbmEQxgpEjcWQ4r6', TRUE);
INSERT INTO attraction_translation (attraction_id, language_code, name, short_description, detailed_description, admission_information, practical_information) VALUES ('34fe6663-359b-5f14-a950-a3714a5d352d', 'hu', 'Bóli-barlang', 'Erdély egyik legnagyobb barlangja, 455 méter hosszú, kiváló akusztikával.', 'Úgy tartják elnevezése a Boli családtól származik, mely a XV. században jelent meg a környéken. A Hátszeg felől Zsil völgye felé haladó főút mellett helyezkedik el a barlang. A Gredistye-Muncsel Csoklovina Nemzeti Park része. Erdély egyik legnagyobb barlangja, hosszúsága 455 méter, 2-3 méteres szintkülönbséggel. A barlang átlagmagassága 10-12 méter, melyet egy patak alakított az évezredek során.
Kitűnő akusztikájának köszönhetően rendezvények színterévé válik olykor. A Zsil völgyi bányászok sokszor elzarándokoltak ide, így egy Rozália oltár is található a barlangban. (Dorina Niță, 2015:132)', 'Belépő: 10 lej/felnőtt, 5 lej/nyugdíjas és gyerek.', NULL);
INSERT INTO attraction_collection (attraction_id, collection_id, display_order) VALUES ('34fe6663-359b-5f14-a950-a3714a5d352d', 'e4b76131-d997-51e2-a1d7-c64a2f10c2d2', 30);
INSERT INTO attraction (id, slug, latitude, longitude, google_maps_url, active) VALUES ('b1fd7575-3c9d-5797-af08-1739252b8936', 'vajdahunyadi-kastely', 45.7489, 22.9017, 'https://www.google.com/maps?q=45.7489,22.9017', TRUE);
INSERT INTO attraction_translation (attraction_id, language_code, name, short_description, detailed_description, admission_information, practical_information) VALUES ('b1fd7575-3c9d-5797-af08-1739252b8936', 'hu', 'Vajdahunyadi kastély', 'A Hunyadi család gótikus-reneszánsz várkastélya, Erdély egyik legszebb műemléke.', '„Ha Visegrád a királyok vára, akkor Vajdahunyad a várak királya!”-Mikszáth Kálmán
Hunyad neve 1265-ös okiratokban tűnik fel először. Bóna István szerint Hunyadvár feltételezhetően Hunod nevű főispán nevéből származtatható. Kuun Géza szerint az is lehetséges, hogy nevének eredete Attila hunjainak nevét őrzi.
A mai vár helyén már a XIII. században állt egy egyszerű vár, melynek a helyére építette Hunyadi János várkastélyát. A római út is ide irányul, így azt is feltételezhetjük, hogy római erőd is létezett a településen. A város feletti bányákban fellelhető a rómaiak bányászata is.
1409-ben Zsigmond király egy adományozó levélben Wajk Buthi királyi katonának, családjának és fiának, akit Hunyadinak nevez, rendelteti a várat.
Hunyadi János két szakaszban építteti a várat. 1441-1446 között megerősíti védelmi rendszerét. 1446-1453 között viszont kibővíti a várat, lakályossá teszi. Ekkor épül a várkápolna, a palotaszárny, a lovagterem és az országházának nevezett díszes terem is.
A XVII. században Bethlen Gábor folytatja a munkálatokat. Saját kedvére alakíttatja a várat. Az ő építkezési szakaszához köthető a Bethlen-szárny megépülése. Hunyad várának számos várura volt, Schreiber István történész úgy tartja, hogy összesen huszonkettő, és a várkastély első urának Hunyadi Jánost nevezi. Az uradalom róla Hunyadi Mátyásra majd Corvin Jánosra szállt. De a Török család is több várurat adott Hunyadnak. A Bethlen család tulajdonában is hosszú évtizedekig volt. I. és II. Apafi Mihály is bírta a várat, utolsó tulajdonosa pedig Bethlen Kata volt. A halálával egy időben a vár a kincstárra szállt.
Az 1800-as években többször is restaurálták a várat, majd 1854. április 13-án Dombrády járási főnök gondatlansága miatt tűz ütött ki, és leégett a várkastély. Ezt követően a szebeni helytartóság ráfordításával elvégezték a legszükségesebb munkálatokat majd Dr. Arányi Lajos budapesti egyetemi tanár karolta fel a vár ügyét. Később Trefor Ágost kultuszminiszter és Hegedüs Candid Lajos műemléki referens folyatták a munkálatokat. Möller István keze alatt pedig megújult a Lovagterem és a Mátyás-traktus. (Schreiber István, 2006:5-25)', 'Egyéni ár: 55 lej/felnőtt, 30 lej/nyugdíjas, 15 lej/gyerek. Csoportos ár (20 fő felett): 45 lej/felnőtt, 25 lej/nyugdíjas, 10 lej/gyerek.', NULL);
INSERT INTO attraction_collection (attraction_id, collection_id, display_order) VALUES ('b1fd7575-3c9d-5797-af08-1739252b8936', 'e4b76131-d997-51e2-a1d7-c64a2f10c2d2', 40);
INSERT INTO attraction (id, slug, latitude, longitude, google_maps_url, active) VALUES ('b1b23035-5d21-561c-a6f3-09ca7c551656', 'oraljaboldogfalvi-reformatus-templom', 45.590558, 22.970021, 'https://www.google.com/maps/place/Biserica+Reformat%C4%83/@45.6926924,23.0696974,9.96z/data=!4m6!3m5!1s0x474e7adca87d0cb9:0x7270a5142a81c5a0!8m2!3d45.590558!4d22.970021!16s%2Fg%2F119pgzwt2?authuser=0&entry=ttu', TRUE);
INSERT INTO attraction_translation (attraction_id, language_code, name, short_description, detailed_description, admission_information, practical_information) VALUES ('b1b23035-5d21-561c-a6f3-09ca7c551656', 'hu', 'Őraljaboldogfalvi református templom', 'Középkori műemléktemplom Erdély legrégebbi falfestményeivel, szemben a Kendeffy-kastéllyal.', 'A települést a XIV. században említik először. 1447-ben A Kende család adományként kapja a helységet Hunyadi Jánostól. A templom a hátszegi királyi várat szolgáló szent helyiség volt, művészettörténészek XIII. századinak vélik. A román építészeti stílus és a gótika vonásai fellelhetőek a templomon, így a két stílus közötti átmeneti időszakban épülhetett. Az egyhajós templom ajtaja félköríves, románkori, felette pedig egy késői gótikus ablak pompázik. Az érdekes műemléktemplom középkori falfestményeket rejt. Erdély legrégebbi falfestményei közé sorolható, korát az 1311-1400 évek közé teszik. Az első szakaszban csak konszekrációs keresztet festettek a falaira, majd az egész templomot újra festették. A falfestmények jellege az olasz mesterek módszerére utal. Piros színárnyalat jellemzi a jeleneteket, melyek fehérrel lettek társítva. A falfestmények vallásos jellegűktől fogva Jézus isteni lényét hivatottak kiemelni (északi oldal felső részében), de a megtestesülés témája és a Boldogságos Szűz ábrázolása is megjelenik (az északi és a déli oldalon). A déli falon az utolsó vacsora jelenete is megtalálható. A XIV. század végén újabb festményekkel egészítették ki a kórusi részt. A templom kezdetben római katolikus volt, Szent Benedek rendjének temploma. A XVIII. századtól már a református egyházhoz tartozott. Ebben a korszakban feltehetően a freskókat mészréteggel vonták be, melyet Rommer Flóris fedezett fel. A feltárást Möller István végezte 1908-ban.
A XX. században minimális karbantartást végeztek a templom állapotán, viszont a falfestmények szakszerű konzerválása még napjainkban sem került sor. (Schreiber István, 2010:8-11)
A templommal szemben található a Kendeffy kastély. A Kendeffy család, mint a Hátszegi-medence és a Zsil völgyének nagyrészű birtoklói, áldozatok árán tettek szert a titulusra.
Hunyadi János kormányzó, 1447. évi levelében felsorolja a hadjáratokat melyekben a Kendeffyek érdemeket szereztek és ennek köszönhetően adományba kapják Boldogasszonyfalvát és további birtokokat.
Hunyadi Mátyás király 1462-ben Körösbányán felsorolja a Kendeffyek hadi érdemeiket és nekik adományozza Várallja birtokot.
II. Ulászló király 1493-ban malomvizi Kendeffy Mihálynak adományozza a Zsil-folyó mentén Pterela, Malee, Ratond, Mwrylowar és Nyak-mezew nezű szántó-, kaszáló- és legeltetőhelyeket.
A Kendeffyek őraljaboldogfalvi kastélyát az 1870-es években építette Kendeffy Árpád neogótikus stílusban angol parkkal körülvéve. (Sólyom-Fekete Ferencz, 1888:75-94)', 'Belépő: 10 lej/fő.', 'Ha marad idő a csillagtúrán, érdemes megtekinteni.');
INSERT INTO attraction_collection (attraction_id, collection_id, display_order) VALUES ('b1b23035-5d21-561c-a6f3-09ca7c551656', 'e4b76131-d997-51e2-a1d7-c64a2f10c2d2', 50);
INSERT INTO attraction (id, slug, latitude, longitude, google_maps_url, active) VALUES ('abd59608-8785-5474-a43c-edd686d9065d', 'demsusi-kotemplom', 45.5819122, 22.8046525, 'https://www.google.com/maps/place/Densu%C8%99+Church/@45.6926924,23.0696974,9.96z/data=!4m6!3m5!1s0x474e68b07b41c453:0x69ea451767d93c05!8m2!3d45.5819122!4d22.8046525!16zL20vMDU1dGxw?authuser=0&entry=ttu', TRUE);
INSERT INTO attraction_translation (attraction_id, language_code, name, short_description, detailed_description, admission_information, practical_information) VALUES ('abd59608-8785-5474-a43c-edd686d9065d', 'hu', 'Demsusi kőtemplom', 'Erdély egyik legkülönlegesebb, római eredetű elemeket is őrző műemléktemploma.', 'Demsus településen található Erdély egyik legkülönlegesebb műemlék temploma. A falu nevét a Kendeffy család leveleiben Domsos, Demses, Damsus néven írják. A XVII. században Demsus tulajdonosai sorában megjelenik egy Lukács de Demptes nevű család, mely a Zeyk, Kenderesi, Mara, Macsesdi, Csongrád, Naláczi, báró Kemény családokkal állt rokonságban. A különleges templom építésének ideje nem egyértelmű, ugyanis falaiban római eredetű feliratok, domborművek láthatóak, így egyes művészettörténészek eredetét a római uralomhoz kötik. A templom építészetileg egy bizáncias és centrális építmény, fellelhetőek rajta a román építészeti stílus jegyei is, a középen elhelyezett tornya pedig arra enged következtetni, hogy XIII. századi építmény. Téglás Gábor történész szerint a freskós a templom katolikus jellegét hangsúlyozzák. A templom legbizarabb része, a templom közepében helyezkedik el, a négyzetes alaprajzú épületrész, mely négy tartóoszlopból áll, erre pedig egy torony nehezedik. Ez a templom legrégebbi része. Később, a XIX. században megjelentek a római oszlopokból emelt támfalak, és valószínűleg ekkor helyezték az apszis tetejére a római kőoroszlánokat is. A legrégebbi falfestmény a bejáratnál látható, Szent Miklós és Szűz Mária ölében tartja a gyermek Jézust. Tehát ez arra utal, hogy a templomot az ők tiszteletükre szentelték fel. A tartóoszlopokon Szent Marina, A Szentháromság és Szent Bertalan képe jelenik meg. A keleti fal felső részén az angyali üdvözlet, és katonaszentek láthatóak. Az oltár körül pedig a trónon ülő gyermek Jézust tartó Szűz Mária, az Apostolok szentáldozása továbbá próféták, főpapok és Jézus van ábrázolva. A falfestmények fő készítője a falra felírt Stefan mestert. A freskók hagyományos példái a középkori erdélyi freskódíszítésnek.
A vidék kiemelkedő családjai a demsusi és reketyefalvi Muzsinák voltak. A család eltűnésével megfigyelhető volt a község vallási megoszlása, megjelent a kálvinista nemesség. A parókiát felváltva használták, Demsuson 1701-ben két pap szolgát, egy görög-katolikus és egy kálvinista. Téglás Gábor 1902-es írásaiban egy anekdótát olvashatunk, miszerint „Befordították az ikonokat a fal felé. Egy óra múlva jött a pópa és visszafordította mindet... ”
A templomban a XX. században több restaurációs munkálatot is végeztek. (Schreiber István, 2010:22-26)', 'Ingyenes.', 'Ha marad idő a csillagtúrán, érdemes megtekinteni.');
INSERT INTO attraction_collection (attraction_id, collection_id, display_order) VALUES ('abd59608-8785-5474-a43c-edd686d9065d', 'e4b76131-d997-51e2-a1d7-c64a2f10c2d2', 60);
INSERT INTO attraction (id, slug, latitude, longitude, google_maps_url, active) VALUES ('0548deb4-e82a-5c27-aa29-c393906bd11c', 'deva-vara', 45.8763, 22.9008, 'https://www.google.com/maps?q=45.8763,22.9008', TRUE);
INSERT INTO attraction_translation (attraction_id, language_code, name, short_description, detailed_description, admission_information, practical_information) VALUES ('0548deb4-e82a-5c27-aa29-c393906bd11c', 'hu', 'Déva vára', 'A Maros völgye fölé magasodó középkori várrom, amely számos történelmi esemény színhelye volt.', '„Tizenkét kőmíves összetanakodék
Magos Déva várát hogy fölépítenék.
Hogy fölépítenék fél véka ezüstér,
Fél véka ezüstér, fél véka aranyér.
Magos Déva várhoz hezzá is kezdöttek
Amit raktak délig leomlott estére
Amit estig raktak leomlott röggelre”-részlet a Kőműves Kelemenné balladából

Kőműves Kelemenné balladájának udvarhelyszéki változata mindenki fülében ismerősen csenghet és ez is hozzájárult a vár népszerűségéhez. Jó elhelyezkedésének köszönhetően a történelemben sok csata részesévé vált. A 184 méter magasban lévő vár már messziről látható, és a várhegyről is belátható a Maros völgye és a Dévai-medence. Az őstörténeti adatok tanúi annak, hogy a Várhegy az ősember idejében is jelentős hely volt. A dákok idejében már őrhely állott a helyén. A rómaiak is birtokba vették az erődítményt, a vár alatt haladt át a hadi út is. Erdély első királyi vára az Árpád-házi királyok idejében Déván épülhetett, feltételezhető, hogy Szent László és Salamon királyok alatt, mely később a tatárjárás áldozatává vált. Az első írásos bizonyíték 1269-ből, IV. Béla király korából való. Több tény is utal arra, hogy a vár már korábban is létezett. A vár első ismert várnagya László mester.
A vegyes házi királyok idejében többször is gazdát cserélt a vár. 1385-től kincstári tulajdonná válik és az erdélyi vajdák székhelye volt. 1440-ben a vár a Hunyadi család tulajdonába kerül I Ulászló király adománya által, és 1504-ig, Corvin János haláláig, a család birtokában maradt.
A következő gondos várúr Szapolyai János volt. Róla fiára János Zsigmondra szállt az uradalom és felesége Izabella királyné többször is megfordult a várban. A várhely és a város virágzása a Hunyadi és Szapolyai családoknak köszönhető, az ők eltűnésükkel egy időben a város jóléte is elkezdett hanyatlani.
A török hadak Erdélyt fenyegették és a dévai várig is elértek. 1550-ben Török János itt vívta meg csatáját az országba benyomulni törekvő sereggel. A sikeres rajtaütést Tinódi Lantos Sebestyén Török János vitézségéről című verses krónikájában énekli meg. A törökök ellen Déva vára volt akkor Erdély legfőbb védelmi pontja. A vár 1551-ben Ferdinánd király szolgálatába került, és hosszú évtizedeken keresztül próbálta a törököket kiszorítani Erdélyből, mígnem 1557-ben Szolimán szultán elfoglalta a várat.
1571-ben Báthory István lett erdély fejedelme. Ez idő alatt raboskodott és halt meg a dévai vár tömlöcében a hitújító, Dávid Ferenc, aki az unitárius egyház megalapítója és első püspöke is volt egyben.
Bethlen Gábor idejében nem csak Erdély, hanem Déva vára és a város is virágzásnak indult. Felépítette a vár lábánál fekvő híres Magna Curiát és a várra is figyelmet fordított. I. és II. Rákóczy György is magáénak tudhatta a várat, ezután pedig az erdélyi fejedelmek birtokát képezte.
Osztrák fennhatóság alá került a vár. Ez idő alatt Gróf Stefan von Steinville generális megerősítette a várat. Az 1784-es Horea, Cloșca és Crișan vezette román parsztfelkelés idején az ide menekülő nemesség védelmét szolgálta.
1817-ben I. Ferenc császár elrendelte a pusztulásnak indult vár restaurálását.
Az 1848-1849-es szabadságharc idejében a vár a császáriak kezében volt, onnan ágyúzták az átvonuló honvédeket. A császáriak kivonulása után a honvédek vették birtokukba a térséget.
1849 augusztus 13-án ismeretlen okból felrobbant a várhegy, ez pedig a vár dicső történelmének a végét jelentette. (Schreiber István, 2005)', 'Jegyár: 9 lej/fő.', 'A felvonó jelenleg nem működik, ezért a látogatókat kisbusz szállítja fel a vár első kapujához.');
