INSERT INTO attraction (id, slug, latitude, longitude, google_maps_url, active) VALUES ('a07eb1fb-5508-53da-a317-18e2d2b09108', 'algyogyfurdo', 45.9219, 23.1725, 'https://maps.app.goo.gl/2fj1HtrgNfQpdVt96', TRUE);
INSERT INTO attraction_translation (attraction_id, language_code, name, short_description, detailed_description, admission_information, practical_information) VALUES ('a07eb1fb-5508-53da-a317-18e2d2b09108', 'hu', 'Algyógyfürdő', 'Már a rómaiak által is használt gyógyvizes fürdőhely négy forrással és a Clocota-vízeséssel.', 'Algyógy közelében négy forrás tör a felszínre. A gyógyvizet már a római korban használták bizonyíték rá az ősrégi medence a fürdőtelep központjában. Jelenleg nem tartalmaz meleg vizet, ugyanis a forrásnál magasabban helyezkedik el. A mai forrás folyamatosan vágja magát be a hegybe, s a kifolyása időszakonként alább kerül. A víz hőmérséklete 31 fok körül ingadozik. A gyógyvíz lefolyása helyenként mésztufás képződményeket hozott létre. Egy vízesés található a Feredőgyógy központjától nem messze, a források lefolyásából, egy meredekebb oldalon vízesés alakult, érdekessége pedig a lerakódott mésztufa a vízesés aljában.
A fürdőtelep már a középkorban is közkedvelt hely volt, Apafi Mihály és Bethlen Gábornak is kedvelt üdülőhelye volt. (Hankó Vilmos, 1884)', 'A római fürdők és a Clocota-vízesés megtekintése ingyenes.', 'Római fürdők: https://maps.app.goo.gl/2fj1HtrgNfQpdVt96. Clocota-vízesés: https://maps.app.goo.gl/61UupBL7wxYkLjm1A.');
INSERT INTO attraction_collection (attraction_id, collection_id, display_order) VALUES ('a07eb1fb-5508-53da-a317-18e2d2b09108', '77c8da33-d2bc-5b44-a35c-a9247353b658', 80);
INSERT INTO attraction (id, slug, latitude, longitude, google_maps_url, active) VALUES ('b75d86ed-062e-5c4f-ad21-4907bf689da0', 'gyulafehervar', 46.0733, 23.58, 'https://www.google.com/maps/place/%22Saint+Michael%22+Cathedral/@46.0680608,23.5662908,16z/data=!4m15!1m8!3m7!1s0x474ea7de25aaeb41:0xeb66ea9250c4464c!2sCetatea+Bastionar%C4%83+Alba+Carolina,+Alba+Iulia!3b1!8m2!3d46.0682065!4d23.5702587!16s%2Fg%2F1ptyl7vls!3m5!1s0x474ea7de727b56cb:0x5e65818a9697c490!8m2!3d46.067558!4d23.569844!16s%2Fm%2F0hzn_h0?authuser=0&entry=ttu', TRUE);
INSERT INTO attraction_translation (attraction_id, language_code, name, short_description, detailed_description, admission_information, practical_information) VALUES ('b75d86ed-062e-5c4f-ad21-4907bf689da0', 'hu', 'Gyulafehérvár', 'Vauban-rendszerű erődítmény és középkori székesegyház, Erdély fejedelmeinek egykori székhelye.', 'Gyulafehérvár már római időben lakott volt, Apullum néven. 1007-ben már itt székelt az erdélyi vajda. A középkori vár a castrum maradványainak felhasználásával épült. Bethlen Gábor megerősített a vár falait, vizes árkot készítettet és két olaszbástyát. A mai Vauban-rendszerű erődítményt Giovanni Morando Visconti császári hadiépítész tervezte. Az 1714-1738 között épült hétágú csillag alaprajzú erődítmény Erdély legnagyobb ilyen jellegű építménye. A bástyák homlokzatán Steinville, Savoyai Jenő és a Habsburgok címere látható. Az erődítmény nagy nyílású kapui igazolják, hogy a várat inkább az ostromágyúk ellen építették mintsem a közelharc vívására. A kapuk gazdagsága a szobrokban mutatkozik. A készítő mester Johannes König. A kapuk közül kiemelkedik a harmadik, amely a keleti kötőgát vonalában helyezkedik el. A hármas nyílású kapuzat tetején III. Károly lovasszobra áll. A kapun látható domborművek Savoyai Jenő herceg török ellenes, győzelmes csatáit ábrázolják.
A székesegyház története kapcsolódik a püspökség történetéhez. A legkorábbi templomot a XI. századra teszik, Szent László király uralkodásának idejére. A XII-XIII században a székesegyházat átépítették három hajóssá és két nyugati toronnyal látták el. Az 1241-es tatárjárást követően a helyreállítási munkák részeként a szentélyt meghosszabbították és ablakait gótikus mérművekkel látták el. 1277-ben a szászok támadnak a püspökségre és olyan mértékű pusztítást végeznek, hogy az oklevelekben még a XV. században is megemlítik. A XV. században Hunyadi János finanszírozta a munkálatokat. 1512-ben a déli bejáratot Lázói (Lászai) János kápolnává alakítatta és korai reneszánsz stílusban egy egyedi építészeti alkotást hozott létre. Ettől a bejárattól keletre pedig Várday Ferenc építetett kápolnát. Amikor 1542-ben a török Budát fenyegette Izabella királyné Erdélybe menekült és Gyulafehérváron telepedett le. A püspöki kápolna egy részébe rendeztek be neki lakhelyet. János Zsigmond idejében a székesegyház a protestánsok kezére kerül és a katolikusok csak 1715-ben kapták vissza. Barokk elemek is találhatók a székesegyházban: a bejárat oromzatán a négy szentet ábrázoló szobor, a sekrestye, a kanonoki stallumok és a főoltár. Erdély legértékesebb történelmi síremlékei itt találhatóak, ugyanis a templom belsejébe folyamatosan temetkeztek. A székesegyházban található: XIV. századi püspöki sírkövek, Hunyadi-tumbák, János Zsigmond és Izabella királyné szarkofágja. Erdély egyik legértékesebb műemléke a gyulafehérvári székesegyház. (Weisz Attila, 2007: 82-84, 174-176, 205-208)', 'A Habsburg vár területén található katolikus és ortodox székesegyház megtekintése ingyenes.', NULL);
